def load() -> pd.DataFrame:
    import pandas as pd
    import numpy as np
    import re

    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Top_Three_Identity_Theft_Reports_by_Year.csv'

    # Try normal CSV first; fall back to raw read if needed.
    try:
        df = pd.read_csv(path)
        df.columns = [str(c).strip() for c in df.columns]

        # Normalize common column names
        colmap = {}
        for c in df.columns:
            cl = c.lower().strip()
            if 'theft' in cl and 'type' in cl:
                colmap[c] = 'theftType'
            elif cl in ['year'] or 'year' in cl:
                colmap[c] = 'year'
            elif 'report' in cl:
                colmap[c] = 'reports'
        df = df.rename(columns=colmap)

        needed = {'theftType', 'year', 'reports'}
        if not needed.issubset(df.columns):
            raise ValueError('Missing expected columns; will use raw parse fallback')

        out = df[['theftType', 'year', 'reports']].copy()

    except Exception:
        raw = pd.read_csv(path, header=None, dtype=str, keep_default_na=False)
        raw = raw.applymap(lambda x: x.strip() if isinstance(x, str) else x)

        header_idx = None
        for i in range(min(len(raw), 200)):
            row = [str(x).lower() for x in raw.iloc[i].tolist() if str(x).strip() != '']
            joined = ' | '.join(row)
            if ('theft type' in joined) and ('year' in joined) and ('report' in joined):
                header_idx = i
                break

        if header_idx is None:
            # If cannot detect, assume first row is header
            header_idx = 0

        df2 = raw.iloc[header_idx + 1:].copy()

        # If it is a single column with commas, split to 3 fields
        if df2.shape[1] == 1:
            split = df2.iloc[:, 0].str.split(',', n=2, expand=True)
            df2 = split

        # Ensure at least 3 columns
        if df2.shape[1] < 3:
            # pad columns
            for _ in range(3 - df2.shape[1]):
                df2[df2.shape[1]] = ''

        df2 = df2.iloc[:, :3]
        df2.columns = ['theftType', 'year', 'reports']
        out = df2

    # Remove obvious footer/notes
    def is_note(x: str) -> bool:
        if x is None or (isinstance(x, float) and np.isnan(x)):
            return True
        s = str(x).strip().lower()
        if s == '':
            return True
        return s.startswith('source') or s.startswith('note') or s.startswith('footnote')

    out = out[~out['theftType'].map(is_note)].copy()

    # Parse numeric year/reports
    out['year'] = pd.to_numeric(out['year'].astype(str).str.extract(r'(\d{4})', expand=False), errors='coerce')
    out['reports'] = pd.to_numeric(out['reports'].astype(str).str.replace(',', '', regex=False).str.extract(r'([0-9]+)', expand=False), errors='coerce')
    out['theftType'] = out['theftType'].astype(str).str.strip()

    out = out.dropna(subset=['theftType', 'year', 'reports'])
    out['year'] = out['year'].astype(int)

    return out.reset_index(drop=True)
